def build(db="data/demo.db", gold="eval/gold.jsonl", backend="hash"):
    store = Store(db, Embedder(backend))
    examples = []
    try:
        for i, (country, commodity, kind, title, question, fact) in enumerate(CASES, 1):
            doc = Document(kind=kind, source="SYNTHETIC-TEST-ONLY", url=f"https://example.invalid/fixture/{i}", title=title + "（合成测试）", body="以下为合成测试数据，不代表真实事件。" + fact, published_at="2026-10-05T08:00:00Z", country=country, commodity=commodity, is_demo=True)
            store.upsert(doc)
            examples.append({"id": f"test-{i:02d}", "question": question, "as_of": "2026-10-08", "kind": kind, "expected_document_ids": [doc.id], "expected_answer": fact, "is_demo": True})
    finally:
        store.close()
    Path(gold).parent.mkdir(parents=True, exist_ok=True)
    Path(gold).write_text("\n".join(json.dumps(x, ensure_ascii=False) for x in examples) + "\n", encoding="utf-8")
    print(f"Wrote {len(examples)} synthetic gold cases to {gold}; db={db}")


if __name__ == "__main__":
    import argparse
    parser = argparse.ArgumentParser()
    parser.add_argument("--db", default="data/demo.db")
    parser.add_argument("--gold", default="eval/gold.jsonl")
    parser.add_argument("--embedding", default="hash", choices=["hash", "fastembed"])
    args = parser.parse_args()
    build(args.db, args.gold, args.embedding)
